select 
from activity


        and (
            title like concat('%', #{keyword}, '%')
            or summary like concat('%', #{keyword}, '%')
            or detail like concat('%', #{keyword}, '%')
            or location like concat('%', #{keyword}, '%')
        )


        and category = #{category}


        and status = #{status}



    order by published_at desc, id desc
    order by (capacity - registered_count) desc, id desc
    order by start_time asc, id desc

limit #{size}
offset #{offset}

select count(1)
from activity


        and (
            title like concat('%', #{keyword}, '%')
            or summary like concat('%', #{keyword}, '%')
            or detail like concat('%', #{keyword}, '%')
            or location like concat('%', #{keyword}, '%')
        )


        and category = #{category}


        and status = #{status}

